{"args":{"content":"package main\n\nimport (\n\t\"net/http\"\n\t\"net/http/httptest\"\n\t\"testing\"\n\t\"time\"\n)\n\nfunc TestSessionLookupTable(t *testing.T) {\n\tnow := time.Date(2025, time.January, 2, 3, 4, 5, 0, time.UTC)\n\n\ttests := []struct {\n\t\tname       string\n\t\tmethod     string\n\t\tsessionID  string\n\t\tseedLive   bool\n\t\twantStatus int\n\t}{\n\t\t{\n\t\t\tname:       \"live session\",\n\t\t\tmethod:     http.MethodGet,\n\t\t\tsessionID:  \"live\",\n\t\t\tseedLive:   true,\n\t\t\twantStatus: http.StatusOK,\n\t\t},\n\t\t{\n\t\t\tname:       \"missing session\",\n\t\t\tmethod:     http.MethodGet,\n\t\t\tsessionID:  \"missing\",\n\t\t\twantStatus: http.StatusNotFound,\n\t\t},\n\t\t{\n\t\t\tname:       \"wrong method\",\n\t\t\tmethod:     http.MethodPost,\n\t\t\tsessionID:  \"live\",\n\t\t\tseedLive:   true,\n\t\t\twantStatus: http.StatusMethodNotAllowed,\n\t\t},\n\t}\n\n\tfor _, tt := range tests {\n\t\tt.Run(tt.name, func(t *testing.T) {\n\t\t\tstore := \u0026sessionStore{sessions: make(map[string]time.Time)}\n\t\t\tstore.now = func() time.Time { return now }\n\t\t\tif tt.seedLive {\n\t\t\t\tstore.sessions[\"live\"] = now.Add(time.Hour)\n\t\t\t}\n\n\t\t\tmux := http.NewServeMux()\n\t\t\tmux.HandleFunc(\"GET /session\", sessionHandler(store))\n\n\t\t\treq := httptest.NewRequest(tt.method, \"/session?id=\"+tt.sessionID, nil)\n\t\t\trecorder := httptest.NewRecorder()\n\t\t\tmux.ServeHTTP(recorder, req)\n\n\t\t\tif recorder.Code != tt.wantStatus {\n\t\t\t\tt.Fatalf(\"status = %d, want %d\", recorder.Code, tt.wantStatus)\n\t\t\t}\n\t\t})\n\t}\n}\n","overwrite":true,"path":"lookup_table_test.go"},"id":"call_write_file_a9cd8cfa11295de0","name":"write_file","runId":"run_20260904182408_7a4c90","schemaVersion":2,"sideEffect":"write","type":"tool_call"}
